// scratch: verify Bun.spawnSync stdin buffer + git plumbing replay approach
import { mkdtempSync, writeFileSync, readFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

function run(cwd: string, args: string[], stdin?: Buffer, env: Record<string, string> = {}) {
  const r = Bun.spawnSync(["git", ...args], {
    cwd,
    stdin: stdin ?? "ignore",
    stdout: "pipe",
    stderr: "pipe",
    env: { ...process.env, ...env },
  });
  if (r.exitCode !== 0) throw new Error(`git ${args.join(" ")} failed: ${r.stderr.toString()}`);
  return r.stdout.toString();
}

const base = mkdtempSync(join(tmpdir(), "f10scratch-"));
const src = join(base, "src");
mkdirSync(src);
run(src, ["init", "-q", "-b", "main"]);
run(src, ["config", "user.email", "[REDACTED_EMAIL]"]);
run(src, ["config", "user.name", "T"]);
writeFileSync(join(src, "README.md"), "# repo\n");
run(src, ["add", "-A"]);
run(src, ["commit", "-qm", "initial commit"]);
writeFileSync(join(src, "a.txt"), "const a = 1;\nif (a < 2) {\n  console.log(\"ok\");\n}\n");
run(src, ["add", "-A"]);
run(src, ["commit", "-qm", "add comparison A\n\nbody line\n"]);
const shaA = run(src, ["rev-parse", "HEAD"]).trim();
console.log("shaA", shaA);

const out = join(base, "copy");
run(base, ["clone", "--no-local", src, out]);
console.log("clone branch", run(out, ["rev-parse", "--abbrev-ref", "HEAD"]).trim());
console.log("log", run(out, ["log", "--format=%H %s"]));

// show -U0 parsing for a root commit and a normal commit
console.log("--- show A ---");
console.log(run(out, ["show", "--format=", "--unified=0", "--no-renames", "--no-color", shaA]));
console.log("--- show root ---");
const root = run(out, ["rev-list", "--max-parents=0", "HEAD"]).trim();
console.log(run(out, ["show", "--format=", "--unified=0", "--no-renames", "--no-color", root]));

// metadata
console.log("parents", JSON.stringify(run(out, ["show", "-s", "--format=%P", shaA]).trim()));
console.log("meta", JSON.stringify(run(out, ["log", "-1", "--format=%an%x00%ae%x00%aI%x00%cn%x00%ce%x00%cI", shaA]).trim()));
console.log("message", JSON.stringify(run(out, ["log", "-1", "--format=%B", shaA])));
console.log("lstree", JSON.stringify(run(out, ["ls-tree", shaA, "a.txt"])));

// blobs + tree building with temp index
const blob = run(out, ["hash-object", "-w", "--stdin"], Buffer.from("const a = 1;\nif (a > 2) {\n  console.log(\"ok\");\n}\n")).trim();
console.log("blob", blob);
const idx = join(base, "tmpindex");
const tree = run(out, ["rev-parse", `${shaA}^{tree}`]).trim();
console.log("tree", tree);
run(out, ["read-tree", tree], undefined, { GIT_INDEX_FILE: idx });
run(out, ["update-index", "--cacheinfo", `100644,${blob},a.txt`], undefined, { GIT_INDEX_FILE: idx });
const newTree = run(out, ["write-tree"], undefined, { GIT_INDEX_FILE: idx }).trim();
console.log("newTree", newTree);
const parent = run(out, ["show", "-s", "--format=%P", shaA]).trim();
const bug = run(
  out,
  ["commit-tree", newTree, "-p", parent, "-F", "-"],
  Buffer.from("add comparison A\n\nbody line\n"),
  {
    GIT_AUTHOR_NAME: "T",
    GIT_AUTHOR_EMAIL: "[REDACTED_EMAIL]",
    GIT_AUTHOR_DATE: "2026-01-01T00:00:00+00:00",
    GIT_COMMITTER_NAME: "T",
    GIT_COMMITTER_EMAIL: "[REDACTED_EMAIL]",
    GIT_COMMITTER_DATE: "2026-01-01T00:00:00+00:00",
  },
).trim();
console.log("bug commit", bug);
console.log(run(out, ["show", "--format=", "--unified=0", "--no-color", bug]));
// preserve-sha check: rebuild unmodified commit and compare
const r2 = run(
  out,
  ["commit-tree", tree, "-p", parent, "-F", "-"],
  Buffer.from("add comparison A\n\nbody line\n"),
  {
    GIT_AUTHOR_NAME: "T",
    GIT_AUTHOR_EMAIL: "[REDACTED_EMAIL]",
    GIT_AUTHOR_DATE: run(out, ["log", "-1", "--format=%aI", shaA]).trim(),
    GIT_COMMITTER_NAME: "T",
    GIT_COMMITTER_EMAIL: "[REDACTED_EMAIL]",
    GIT_COMMITTER_DATE: run(out, ["log", "-1", "--format=%cI", shaA]).trim(),
  },
).trim();
console.log("rebuilt equals original:", r2 === shaA, r2, "message roundtrip", JSON.stringify(readFileSync(join(out, "a.txt"), "utf8")));
run(out, ["reset", "--hard", bug]);
console.log("worktree after reset:", JSON.stringify(readFileSync(join(out, "a.txt"), "utf8")));
console.log("status", run(out, ["status", "--porcelain"]));

