    expect(a.operator).not.toBe("<");
    expect(c.line).toBe(2);
    expect(c.originalOperator).toBe(">=");
    expect(c.operator).not.toBe(">=");

    for (const [entry, file, original] of [
      [a, "a.txt", "if (a < 2) {"],
      [c, "c.txt", "  return x >= 0;"],
    ] as [PlantedBug, string, string][]) {
      const flipped = original.replace(entry.originalOperator, entry.operator);

      // The bug commit keeps the original subject and shows exactly the flipped line.
      expect(git(copy, ["cat-file", "-t", entry.commit])).toBe("commit");
      expect(git(copy, ["show", "-s", "--format=%s", entry.commit])).toBe(entry.sourceCommit === shaA ? "add comparison A" : "add comparison C");
