    const base = tmp("outdir");
    const { dir: src } = sourceRepo("outdir", [{ file: "a.txt", content: "if (a < 2) {}\n", message: "add comparison" }]);
    const copy = join(base, "copy");
    mkdirSync(copy, { recursive: true });
