ok(src, ["init", "-q", "-b", "main"]);
ok(src, ["config", "user.email", "[REDACTED_EMAIL]"]);
ok(src, ["config", "user.name", "Planted Test"]);
writeFileSync(join(src, "README.md"), "# repo\n");
ok(src, ["add", "-A"]);
ok(src, ["commit", "-q", "--no-gpg-sign", "-m", "initial commit"]);
writeFileSync(join(src, "notes.txt"), "just some notes\n");
ok(src, ["add", "-A"]);
ok(src, ["commit", "-q", "--no-gpg-sign", "-m", "add skip note"]);
const notes = ok(src, ["rev-parse", "HEAD"]).trim();

const copy = join(base, "copy");
ok(base, ["clone", "--no-local", src, copy]);
console.log("copy notes:", ok(copy, ["rev-parse", "HEAD"]).trim(), "source notes:", notes);

