const message = ok(copy, ["log", "-1", "--format=%B", notes]);
console.log("meta:", JSON.stringify(meta), "message:", JSON.stringify(message));
console.log("raw commit object:\n" + ok(copy, ["cat-file", "commit", notes]));
const parents = ok(copy, ["show", "-s", "--format=%P", notes]).trim().split(/\s+/).filter(Boolean);
const tree = ok(copy, ["rev-parse", `${notes}^{tree}`]).trim();
const env = {
  GIT_AUTHOR_NAME: meta[0] as string,
  GIT_AUTHOR_EMAIL: meta[1] as string,
  GIT_AUTHOR_DATE: meta[2] as string,
  GIT_COMMITTER_NAME: meta[3] as string,
  GIT_COMMITTER_EMAIL: meta[4] as string,
  GIT_COMMITTER_DATE: meta[5] as string,
};
const rebuilt = ok(copy, ["commit-tree", tree, ...parents.flatMap((p) => ["-p", p]), "-F", "-"], Buffer.from(message), env).trim();
console.log("rebuilt:", rebuilt, "equal:", rebuilt === notes);
console.log("raw rebuilt object:\n" + ok(copy, ["cat-file", "commit", rebuilt]));

