// scratch6: build commit objects by hand so ids stay byte-exact
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

function run(cwd: string, args: string[], stdin?: Buffer) {
  return Bun.spawnSync(["git", "-c", "color.ui=false", ...args], { cwd, stdin: stdin ?? "ignore", stdout: "pipe", stderr: "pipe" });
}
function ok(cwd: string, args: string[], stdin?: Buffer): Buffer {
  const r = run(cwd, args, stdin);
  if (r.exitCode !== 0) throw new Error(`git ${args.join(" ")}: ${r.stderr.toString()}`);
  return r.stdout;
}

const base = mkdtempSync(join(tmpdir(), "f10scratch6-"));
const src = join(base, "source");
mkdirSync(src);
ok(src, ["init", "-q", "-b", "main"]);
ok(src, ["config", "user.email", "[REDACTED_EMAIL]"]);
ok(src, ["config", "user.name", "Planted Test"]);
const mk = (file: string, content: string, msg: string) => {
  writeFileSync(join(src, file), content);
  ok(src, ["add", "-A"]);
  ok(src, ["commit", "-q", "--no-gpg-sign", "-m", msg]);
  return ok(src, ["rev-parse", "HEAD"]).toString().trim();
};
mk("README.md", "# repo\n", "initial commit");
const notes = mk("notes.txt", "notes\n", "add skip note");
mk("a.txt", "if (a < 2) {}\n", "add comparison");

const copy = join(base, "copy");
ok(base, ["clone", "--no-local", src, copy]);

const raw = ok(copy, ["cat-file", "commit", notes]);
const text = raw.toString();
const sep = text.indexOf("\n\n");
const headLines = text.slice(0, sep).split("\n");
const message = raw.subarray(Buffer.byteLength(text.slice(0, sep)) + 2);
console.log("head:", JSON.stringify(headLines), "message:", JSON.stringify(message.toString()));

const rebuild = (tree: string, parents: string[], kept: string[], msg: Buffer) =>
  ok(copy, ["hash-object", "-t", "commit", "-w", "--stdin"],
    Buffer.concat([Buffer.from([`tree ${tree}`, ...parents.map((p) => `parent ${p}`), ...kept].join("\n") + "\n\n"), msg])).toString().trim();

const tree = ok(copy, ["rev-parse", `${notes}^{tree}`]).toString().trim();
const parents = (headLines.find((l) => l.startsWith("parent ")) ?? "").replace("parent ", "").trim();
const kept = headLines.filter((l) => !l.startsWith("tree ") && !l.startsWith("parent "));
const same = rebuild(tree, [parents], kept, message);
console.log("rebuilt identical:", same === notes, same, notes);

// modified tree (the planted bug) still parses
const blob = ok(copy, ["hash-object", "-w", "--stdin"], Buffer.from("notes changed\n")).toString().trim();
const idx = join(base, "idx");
ok(copy, ["read-tree", `${notes}^{tree}`], undefined as never);
const env = { GIT_INDEX_FILE: idx };
run(copy, ["read-tree", `${notes}^{tree}`], undefined);
Bun.spawnSync(["git", "update-index", "--add", "--cacheinfo", `100644,${blob},notes.txt`], { cwd: copy, env: { ...process.env, GIT_INDEX_FILE: idx } });
const newTree = ok(copy, ["write-tree"]).toString().trim();
const bug = rebuild(newTree, [parents], kept, message);
console.log("bug commit:", bug);
console.log(ok(copy, ["show", "--format=", "--unified=0", bug]).toString());
console.log("subject:", ok(copy, ["show", "-s", "--format=%s", bug]).toString().trim());

// fix commit: bump the committer date on the kept line
const committer = kept.find((l) => l.startsWith("committer "));
if (!committer) throw new Error("no committer line");
const m = / (\d+) ([+-]\d{4})$/.exec(committer);
if (!m) throw new Error("no date in committer line");
const bumped = committer.replace(/ (\d+) ([+-]\d{4})$/, ` ${Number(m[1]) + 1} ${m[2]}`);
const fixKept = kept.map((l) => (l === committer ? bumped : l));
const fixMsg = Buffer.from("fix: restore the comparison in notes.txt\n");
const fix = rebuild(tree, [bug], fixKept, fixMsg);
console.log("fix commit:", fix, "subject:", ok(copy, ["show", "-s", "--format=%s", fix]).toString().trim());
console.log("fix diff:", ok(copy, ["show", "--format=", "--unified=0", fix]).toString());
console.log("verify both:", run(copy, ["fsck", "--no-progress"]).exitCode === 0);

