// CLI smoke test for scripts/planted/plant.ts: builds a tiny repo, runs the CLI, checks the key.
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

function ok(cwd: string, args: string[]) {
  const r = Bun.spawnSync(["git", ...args], { cwd, stdout: "pipe", stderr: "pipe" });
  if (r.exitCode !== 0) throw new Error(`git ${args.join(" ")}: ${r.stderr.toString()}`);
  return r.stdout.toString().trim();
}

const base = mkdtempSync(join(tmpdir(), "f10cli-"));
const src = join(base, "source");
mkdirSync(src);
ok(src, ["init", "-q", "-b", "main"]);
ok(src, ["config", "user.email", "[REDACTED_EMAIL]"]);
ok(src, ["config", "user.name", "T"]);
writeFileSync(join(src, "a.js"), "if (count >= limit) { stop(); }\n");
ok(src, ["add", "-A"]);
ok(src, ["commit", "-qm", "add guard"]);
const sha = ok(src, ["rev-parse", "HEAD"]);

const cwd = new URL("../..", import.meta.url).pathname;
const run = Bun.spawnSync(
  ["bun", "scripts/planted/plant.ts", "--source", src, "--out", join(base, "copy"), "--key", join(base, "key.json"), "--seed", "4", "--commit", sha],
  { cwd, stdout: "pipe", stderr: "pipe" },
);
console.log("exit:", run.exitCode);
console.log(run.stdout.toString().trim());
if (run.exitCode !== 0) console.log(run.stderr.toString());
console.log(JSON.stringify(JSON.parse(readFileSync(join(base, "key.json"), "utf8")).planted, null, 2));

const bad = Bun.spawnSync(["bun", "scripts/planted/plant.ts"], { cwd, stdout: "pipe", stderr: "pipe" });
console.log("no args exit:", bad.exitCode, bad.stderr.toString().trim().split("\n")[0]);

